//! KillrVideo with cqlc: the real 3.x schema from github.com/KillrVideo/killrvideo-data, typed query
//! functions generated by `cqlc generate`, run against a live node (`CQLC_NODE`, default 127.0.0.1:9042).

#[rustfmt::skip]
mod queries;

use queries::*;
use scylla::client::session_builder::SessionBuilder;
use scylla::value::CqlTimestamp;
use scylla::errors::TranslationError;
use scylla::policies::address_translator::{AddressTranslator, UntranslatedPeer};
use std::net::SocketAddr;
use std::sync::Arc;
use uuid::Uuid;

struct Pin(SocketAddr);

#[async_trait::async_trait]
impl AddressTranslator for Pin {
    async fn translate_address(&self, _: &UntranslatedPeer) -> Result<SocketAddr, TranslationError> {
        Ok(self.0)
    }
}

const SCHEMA: &str = include_str!("../schema/schema.cql");

fn ms(day: i64, n: i64) -> CqlTimestamp {
    CqlTimestamp(1_700_000_000_000 + day * 86_400_000 + n * 1000)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let node = std::env::var("CQLC_NODE").unwrap_or_else(|_| "127.0.0.1:9042".into());
    // With Docker port mappings the node advertises its container address; pin every peer to the address we dialled.
    let addr: SocketAddr = std::net::ToSocketAddrs::to_socket_addrs(&node)?.next().ok_or("bad CQLC_NODE")?;
    let session = SessionBuilder::new().known_node_addr(addr).address_translator(Arc::new(Pin(addr))).build().await?;
    session
        .query_unpaged("CREATE KEYSPACE IF NOT EXISTS killrvideo WITH replication = {'class': 'NetworkTopologyStrategy', 'replication_factor': 1}", &[])
        .await?;
    session.use_keyspace("killrvideo", false).await?;
    for stmt in SCHEMA.split(';').map(str::trim).filter(|s| !s.is_empty()) {
        session.query_unpaged(stmt.to_string(), &[]).await?;
    }
    let q = Queries::new(Arc::new(session)).await?;

    // a user uploads three videos on two days
    let user = Uuid::new_v4();
    q.create_user(CreateUserParams { userid: user, firstname: Some("Ada".into()), lastname: Some("Lovelace".into()), email: Some("ada@example.com".into()), created_date: Some(ms(0, 0)) }).await?;
    let mut videos = Vec::new();
    for (i, (day, name)) in [(0, "Intro to Cassandra"), (0, "Data modeling"), (1, "Compaction explained")].into_iter().enumerate() {
        let v = Uuid::new_v4();
        videos.push(v);
        let added = ms(day, i as i64);
        q.add_video(AddVideoParams { videoid: v, userid: Some(user), name: Some(name.into()), description: None, location: Some(format!("https://example.com/{v}")), location_type: Some(1), preview_image_location: None, tags: Some(["cassandra".to_string()].into()), added_date: Some(added) }).await?;
        q.add_user_video(AddUserVideoParams { userid: user, added_date: added, videoid: v, name: Some(name.into()), preview_image_location: None }).await?;
        q.add_latest_video(AddLatestVideoParams { yyyymmdd: format!("day{day}"), added_date: added, videoid: v, userid: Some(user), name: Some(name.into()), preview_image_location: None }).await?;
    }

    // typed reads: absent cells are Option, primary keys never are
    let u = q.get_user(user).await?.expect("user exists");
    assert_eq!(u.email.as_deref(), Some("ada@example.com"));
    let vids = q.videos_of_user(user).await?;
    assert_eq!(vids.len(), 3);
    assert!(vids[0].added_date.0 >= vids[1].added_date.0, "clustering order is added_date DESC");
    println!("videos of user, newest first: {:?}", vids.iter().map(|v| v.name.clone().unwrap_or_default()).collect::<Vec<_>>());
    assert_eq!(q.latest_videos_of_day("day0".into()).await?.len(), 2);

    // ratings and a counter table
    for r in 3..=5 {
        q.rate_video(RateVideoParams { videoid: videos[0], userid: Uuid::new_v4(), rating: Some(r) }).await?;
    }
    assert_eq!(q.ratings_of_video(videos[0]).await?.len(), 3);
    for _ in 0..4 {
        q.count_playback(videos[0]).await?;
    }
    let stats = q.playback_stats(videos[0]).await?.expect("stats row");
    println!("playback views: {:?}", stats.views);
    assert_eq!(stats.views.map(|c| c.0), Some(4));
    println!("ok: 13 generated queries exercised against the real KillrVideo schema");
    Ok(())
}
